  "mainEntity": [
    {
      "@type": "Question",
      "name": "What investor relations solutions does PR Newswire offer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "PR Newswire offers integrated investor relations solutions to help public companies communicate accurately, consistently and confidently with investors and financial media. Solutions include secure financial news distribution, earnings release dissemination, IR and ESG websites, webcasts and teleconferencing events, and targeted outreach to investors and analysts through Market Lists, powered by Irwin."
      }
    },
    {
      "@type": "Question",
      "name": "How does PR Newswire help public companies distribute financial news?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "PR Newswire distributes financial news through one of the industry’s most established and trusted global disclosure networks, helping public companies meet disclosure requirements while reaching investors, analysts and financial media at scale. Secure technology, editorial review and proven distribution processes help companies reduce risk, maintain consistency and ensure financial news is delivered accurately and reliably across key investor channels."
      }
    },
    {
      "@type": "Question",
      "name": "What is an Investor Relations (IR) website?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "An investor relations website is a dedicated section of a company’s website that provides investors, analysts and media with timely access to key financial information such as earnings releases, material news, financial statements, event replays, stock data and governance content. A well-maintained IR website helps reinforce transparency, support compliance, and build long-term investor confidence."
      }
    },
    {
      "@type": "Question",
      "name": "Does PR Newswire support investor webcasts and earnings calls?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, PR Newswire supports audio and video investor webcasts, earnings calls and virtual investor events, including end-to-end production and event management services. Experienced webcast producers help ensure professional execution, reliable delivery and seamless experience for both presenters and investors."
      }
    }
  ]
}

